  "claims": [
    {
      "claim": "En France, la protection contre le licenciement en cas de maladie ou d'accident varie en fonction de la durée du contrat de travail, de la durée de l'absence, et de la nature du contrat (CDD, CDI, période d'essai).",
      "verdict": "unverifiable"
    },
    {
      "claim": "Pendant la période d'essai, l'employeur peut rompre le contrat plus librement, mais il doit toujours respecter un préavis (sauf en cas de faute grave ou de force majeure).",
      "verdict": "unverifiable"
    },
    {
      "claim": "En cas de maladie ou d'accident survenant durant la période d'essai, le contrat n'est pas automatiquement prolongé.",
      "verdict": "unverifiable"
    },
    {
      "claim": "La période d'essai est généralement suspendue le temps de l'absence (selon les règles du Code du travail, notamment l'article L. 1226-21).",
      "verdict": "unverifiable"
    },
    {
      "claim": "Si la maladie ou l'accident se prolonge au-delà de la période d'essai prévue initialement, celle-ci est prolongée du temps de l'absence.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Une fois la période d'essai terminée (et le salarié toujours en poste), l'employeur ne peut pas licencier un salarié pour le seul motif qu'il est malade ou accidenté.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Il existe une protection spécifique contre le licenciement pour motif de santé.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Par exemple, un salarié en arrêt maladie bénéficie d'une protection durant les périodes d'arrêt et pendant les 30 jours suivant la reprise du travail (article L. 1132-1 du Code du travail).",
      "verdict": "unverifiable"
    },
    {
      "claim": "Après la période d'essai (CDI), le délai de congé dépend de l'ancienneté du salarié.",
      "verdict": "unverifiable"
    }
  ],
